import{z as o,x as B,o as s,c as d,q as A,j as i,D as e,d as r,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"时钟偏斜与时钟树综合","description":"","frontmatter":{"title":"时钟偏斜与时钟树综合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-skew-cts.md","filePath":"cs/clock-skew-cts.md","lastUpdated":1791063341000}'),p={name:"cs/clock-skew-cts.md"};function S(T,a,c,C,D,m){const t=B("Mermaid");return s(),d("div",null,[a[2]||(a[2]=A('<h1 id="时钟偏斜与时钟树综合" tabindex="-1">时钟偏斜与时钟树综合 <a class="header-anchor" href="#时钟偏斜与时钟树综合" aria-label="Permalink to &quot;时钟偏斜与时钟树综合&quot;">​</a></h1><div class="epigraph"><p>STA 里的时钟到达时间不是理想零：树要长到每个触发器，综合的目标是把偏斜收进预算，而不是把时钟当理想线网。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Weste and Harris, CMOS VLSI Design 整理</footer></div><p><a href="/cs/sta">上一课</a>把 slack 写成路径延迟对周期。组成课的<a href="/cs/clock-jitter">时钟树与抖动</a>已定性 skew 与 jitter。缺口是实现：<strong>时钟树综合（CTS）</strong>——在网表上插入缓冲树或网格，让 STA 用真实的时钟到达时间，而不是假定同源边沿同时到。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>综合初期常用理想时钟。布局后线长不同，接收 FF 的边沿可早可晚。有用偏斜（borrow）能缓解建立，有害偏斜恶化保持。CTS：以时钟根为源，按扇出与延迟插入缓冲，最小化 skew 或按预算分配。缺口不是再写建立不等式，而是这棵树从哪来、如何进 STA。<span class="marginnote">术语翻译：时钟树综合（CTS）就是「给时钟修一张按预算分发的公交网」——以时钟根为总站，插一级级缓冲当站点，让边沿按计划时刻到达每个触发器，而不是各听天由命。</span></p><p>门控时钟是树上的与门，须平衡以使能域与非门控域之间的偏斜仍可控——功耗课再讲门控，本课承认树的拓扑因此分叉。</p><h3 id="cts-不是「再综合一次组合逻辑」" tabindex="-1">CTS 不是「再综合一次组合逻辑」 <a class="header-anchor" href="#cts-不是「再综合一次组合逻辑」" aria-label="Permalink to &quot;CTS 不是「再综合一次组合逻辑」&quot;">​</a></h3><p>时钟网有特殊设计规则（屏蔽、宽度），缓冲器选时钟专用单元。把时钟当普通数据网交给缓冲插入，skew 与串扰会失控。组成课的 H 树是拓扑直觉；ASIC CTS 是工具在合法位置上的解。</p><p><span class="marginnote">Weste/Harris CMOS VLSI 讲时钟分布。Harris DDCA 把 skew 写入时序。本课不画某工艺的 H 树坐标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CTS 前：理想时钟 STA，看逻辑是否过关。CTS 后：传播时钟 STA，时钟路径延迟进入建立/保持。有用 skew：故意让捕获沿晚到。网格（mesh）降低局部 skew，功耗更高。FPGA 有现成全局时钟网络，CTS 概念对应「用专用时钟布线」，不是自由缓冲树。<span class="marginnote">数字实例：周期 2 ns 的设计里某条路径逻辑要 1.9 ns，眼看建立违例；让捕获端时钟晚到 0.15 ns，等效预算放宽到 2.15 ns，建立过了——但若晚到过头，同一边沿相对下一拍就「太早」，保持开始出问题。借时间永远要两头验。</span></p>',11)),(s(),i(l,null,{default:e(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%97%B6%E9%92%9F%E6%A0%B9%22%5D%20--%3E%20CTS%5B%22%E6%8F%92%E5%85%A5%E7%BC%93%E5%86%B2%E6%A0%91%20%2F%20%E7%BD%91%E6%A0%BC%22%5D%0A%20%20CTS%20--%3E%20ARR%5B%22%E5%90%84%20FF%20%E5%88%B0%E8%BE%BE%E6%97%B6%E9%97%B4%22%5D%0A%20%20ARR%20--%3E%20STA%5B%22%E4%BC%A0%E6%92%AD%E6%97%B6%E9%92%9F%20STA%22%5D%0A%20%20STA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%8D%E4%BD%8D%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"抖动仍来自 PLL/振荡器，CTS 不消灭 jitter，只分配延迟。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"复位同步、门控、DFT 扫描时钟切换都会改树。后课复位策略必须与 CTS 同域：异步复位释放若相对时钟偏斜过大，会在释放沿造成复位恢复时间违例——那是复位课的缺口，本课先把树钉成「有到达时间的网」。",-1)),(s(),i(l,null,{default:e(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20LATE%5B%22%E6%8A%8A%E6%8D%95%E8%8E%B7%20FF%20%E7%9A%84%E6%97%B6%E9%92%9F%E5%88%B0%E8%BE%BE%E6%95%85%E6%84%8F%E6%8E%A8%E6%99%9A%22%5D%20--%3E%20GAIN%5B%22%E5%BB%BA%E7%AB%8B%E6%A3%80%E6%9F%A5%E7%AD%89%E6%95%88%E5%8F%98%E5%AE%BD%EF%BC%9A%E8%A3%95%E9%87%8F%E5%9B%9E%E6%9D%A5%22%5D%0A%20%20LATE%20--%3E%20RISK%5B%22%E5%90%8C%E4%B8%80%E8%BE%B9%E6%B2%BF%E7%9B%B8%E5%AF%B9%E4%B8%8A%E4%B8%80%E6%8B%8D%E5%8F%98%E6%97%A9%22%5D%0A%20%20RISK%20--%3E%20HOLDV%5B%22%E4%BF%9D%E6%8C%81%E6%A3%80%E6%9F%A5%E8%A2%AB%E5%92%AC%EF%BC%9A%E6%97%A7%E5%80%BC%E5%8F%AF%E8%83%BD%E8%A2%AB%E6%96%B0%E6%95%B0%E6%8D%AE%E5%86%B2%E6%8E%89%22%5D%0A%20%20GAIN%20--%3E%20BOTH%5B%22%E6%9C%89%E7%94%A8%E5%81%8F%E6%96%9C%E5%BB%BA%E7%AB%8B%E4%B8%8E%E4%BF%9D%E6%8C%81%E4%B8%A4%E5%A4%B4%E9%83%BD%E8%A6%81%E9%87%8D%E9%AA%8C%22%5D%0A%20%20HOLDV%20--%3E%20BOTH%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">这张图回答「有用偏斜借来的时间从哪来、代价是什么」：借的是上一拍的保持裕量。初学者容易只盯建立报表欢呼，忘了同一次推迟让保持路径变紧——STA 的两个检查方向相反，改一边必须复查另一边。</span></p><p><span class="marginnote">常见误区：FPGA 用户以为也该「长一棵树」。FPGA 里全局时钟网络是工厂造好的专用低偏斜布线，你只需把时钟指到这些资源上；让时钟走通用布线，偏斜与抖动都会失控——ASIC 那种自由插缓冲的 CTS 在 FPGA 里并不存在。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 PLL 环路滤波器设计，不把封装 SSO 噪声写成完整 SI。不进入光刻镜头加热导致的延迟漂移。不把比特币矿机当案例。</p><p>后课默认：时钟到达时间由 CTS（或 FPGA 时钟网）给出；偏斜进入 STA，不是零。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>STA 需要真实时钟到达；CTS 长出那棵树。</li><li>有用/有害偏斜改建立与保持。</li><li>FPGA 用专用时钟资源，ASIC 用缓冲树或网格。</li><li>出处：Harris and Harris；Weste and Harris, CMOS VLSI Design。</li></ul>',7))])}const k=o(p,[["render",S]]);export{h as __pageData,k as default};
